async function loadStageEntries(cases) {
  const map = {};
  const ids = (cases || []).map((c) => c.id);
  if (!ids.length) return map;
  try {
    const { data, error } = await inChunks(ids, (sl) => db.from("case_events").select("case_id,event,created_at").in("case_id", sl).in("event", ["stage_changed", "stage_change", "case_created"]));
    if (error) return map;
    (data || []).forEach((e) => {
      if (!e || !e.case_id || !e.created_at) return;
      if (!map[e.case_id] || e.created_at > map[e.case_id]) map[e.case_id] = e.created_at;
    });
  } catch (_) { /* degrade gracefully — no age line, no colour */ }
  return map;
}
