  if ($("#app-view").classList.contains("hidden")) return; // not in the app (login screen) — ignore
  /* G1R-1 — a second-layer capture is up: Back cancels the CAPTURE, exactly as Escape and a backdrop click
     already do, and never the modal or the page underneath it. */
  const ovl = overlayStack[overlayStack.length - 1];
