  enquiry: ["act-appt"], fact_find: ["act-appt"], decision_in_principle: ["act-appt"], application: ["act-appt"], offer: [], exchange: [],
  /* A COMPLETED case has no Advance button, so one stage action fits. On a case still tracking a rate it is
     📌 Rate-end outcome — the decision the retention book is waiting on… */
  completed: ["act-rate-outcome"],
  // A dead case has one job: say why. ✏️ Record reason is the hero here and there is room for it.
  not_proceeding: ["act-record-reason"],
