  const overflowHtml = ((opts && opts.menuLeadHtml) || "")
    + (demoted.length ? `<div class="more-actions-group">For a case at ${esc(STAGE_LABEL[stage] || String(stage).replace(/_/g, " "))}</div>` : "")
