  let stageEntry = {};
  /* R87 · B1 (panel 03 #1): THE PROMPT IS THE DEFAULT. Four controls moved a case one stage and only two of
     them asked the stage-entry questions; which data a case carried depended on which finger was used. */
  const askStageEntry = opts.promptStageEntry != null ? !!opts.promptStageEntry : !silent;
