/* R13 · M-23/M-25: THE CLAWBACK WINDOW get_protection_pipeline deliberately returns only the OPEN protection
   statuses, so this panel cannot be built from `scoped` — a policy that was taken is exactly what it left out. … */
function renderClawbackWindow(pre) {
  const panel = $("#prot-clawback-panel");
  if (!panel) return;
  pre = pre || {};
  if (pre.absent) { panel.classList.add("hidden"); return; }
  if (pre.error) {
    panel.classList.remove("hidden");
    $("#prot-clawback-list").innerHTML = emptyState({ headline: "Clawback window unavailable just now", sub: pre.error.message || "" });   // R88 · C — the house empty state
    return;
  }
  const rows = Array.isArray(pre.rows) ? pre.rows : [];
  panel.classList.remove("hidden");
  const money = showMoney();
  const noDate = rows.filter((r) => !r.policy_start_date);
  const inWindow = rows
    .map((r) => ({ ...r, months: clawbackMonthsElapsed(r.policy_start_date) }))
    .filter((r) => r.months != null && r.months >= 0 && r.months < CLAWBACK_MONTHS)
    .sort((a, b) => (b.months - a.months) || 0);   // closest to falling out of the window first
  const nameOf = (r) => [r.clients && r.clients.first_name, r.clients && r.clients.last_name].filter(Boolean).join(" ") || "(client not on file)";
  const countEl = $("#prot-clawback-count");
  countEl.textContent = inWindow.length;
  countEl.className = "badge " + (inWindow.length ? "amber" : "grey");
  /* R87 · book · C5 — one line on the panel; the 60-word basis keeps its id inside the fold. */
  const clawLine = $("#prot-clawback-line");
  if (clawLine) clawLine.textContent = `Policies taken in the last ${CLAWBACK_MONTHS} months, where a lapse could still claw commission back. ${CLAWBACK_MONTHS} months is an assumption — check the provider's schedule.`;
  const clawHow = $("#prot-clawback-how");
  if (clawHow) clawHow.innerHTML = howFold({ id: "prot-clawback-how-fold", title: "How this is counted", html: `<p id="prot-clawback-basis">`
    + `Policies recorded as taken whose start date falls inside the last <strong>${CLAWBACK_MONTHS} months</strong> — the period in which a provider would typically reclaim the commission if the policy lapses. `
    + `<strong>${CLAWBACK_MONTHS} months is an assumption</strong>, not a figure read from anywhere: providers differ, and this app holds no per-provider clawback terms. Check the provider's own schedule before you rely on a number here.`
    + (money ? "" : ` Commission is shown to the Owner only; the count and the dates are not money and are shown to everyone.`)
    + ` Not scoped by Mine / Unassigned / All: a clawback is money the firm pays back, whoever's case it was.</p>` });
  /* THE HONEST HALF, and the reason the panel exists at all. A policy with no start date is not a policy
     outside the window — it is a policy whose window nobody can see. */
  $("#prot-clawback-nodate").innerHTML = noDate.length
    ? `<strong id="prot-clawback-nodate-n">${noDate.length} polic${noDate.length === 1 ? "y has" : "ies have"} no start date recorded</strong> — add it on the case (Protection section); they are listed below the table.`
    : rows.length ? `Every policy taken has a start date recorded. 👍` : "";
  const rowHtml = (r) => `<tr data-case="${esc(r.id)}">
      <td><span class="prot-client" onclick="openCase('${jsArg(r.id)}')">${esc(nameOf(r))}</span></td>
      <td>${fmtD(r.policy_start_date)}</td>
      <td class="clawback-months">${r.months} of ${CLAWBACK_MONTHS}</td>
      <td class="clawback-months${CLAWBACK_MONTHS - r.months <= 3 ? " clawback-left-hot" : ""}">${CLAWBACK_MONTHS - r.months}</td>
      ${money ? `<td class="num">${r.protection_commission > 0 ? fmtM(r.protection_commission) : '<span class="cs-muted">none recorded</span>'}</td>` : ""}
      <td>${r.assigned_to ? esc(staffName(r.assigned_to)) : '<span class="cs-muted">— unassigned —</span>'}</td>
      <td class="clawback-open"><button class="btn btn-sm" onclick="openCase('${jsArg(r.id)}')">Open</button></td>
    </tr>`;
  $("#prot-clawback-list").innerHTML = (inWindow.length ? `<table class="imp-table" id="prot-clawback-table">
      <tr><th>Client</th><th>Policy started</th><th>Months elapsed</th><th>Months left in window</th>${money ? "<th>Commission</th>" : ""}<th>Adviser</th><th></th></tr>
      ${inWindow.map(rowHtml).join("")}
    </table>` : emptyState({ headline: `No policy started in the last ${CLAWBACK_MONTHS} months`, sub: rows.length ? "Nothing is inside a clawback window." : "" }))
    + (noDate.length ? `<div class="dq-notice" id="prot-clawback-nodate-list">
      <strong>No start date — window cannot be watched:</strong>
      ${noDate.map((r) => `<button type="button" class="btn btn-sm" onclick="openCase('${jsArg(r.id)}')">${esc(nameOf(r))}</button>`).join(" ")}
    </div>` : "");
}
