    const cta = useNps
      ? [`How likely are you to recommend us to a friend?`, `😍 Loved it · 😊 Good · 😐 OK · 😕 Meh · 😞 Poor (each a one-tap answer)`]
      : (link ? [`Leave a review → ${link}`] : []);
