    ids: { bar: "sms-bulk-bar", n: "sms-bulk-n", cancel: "sms-bulk-cancel", retry: "sms-bulk-retry", clear: "sms-bulk-clear" },
    addrCol: "to_phone", typeCol: "sms_type",
    contact: "phone", addrWord: "phone number", noAddr: "no number",
    noun: "SMS", nouns: "SMS", Noun: "SMS", count: (n) => `${n} SMS`,
    stopBefore: "one before the 8:05am run", pickedBy: "the 8:05am SMS run or by “Send SMS now”",
    tags: { retry: "retrySms", read: "bulkCancelSms", write: "bulkCancelSms" }, retryAllFn: "retryAllFailedSms",
    label: (t) => smsTypeLabel(t), sel: () => smsSel, busy: false,
